// Extraire le texte OCR du document Paperless
const doc = $input.first().json;
const ocrText = doc.content || doc.original_file_name || '';
const documentId = doc.id;
const fileName = doc.original_file_name || doc.title;

if (!ocrText || ocrText.trim().length < 20) {
  return [{
    json: {
      document_id: documentId,
      file_name: fileName,
      ocr_text: ocrText,
      error: 'Texte OCR trop court ou vide',
      skip: true
    }
  }];
}

return [{
  json: {
    document_id: documentId,
    file_name: fileName,
    ocr_text: ocrText.substring(0, 8000),
    skip: false
  }
}];

// Parser la réponse JSON de Mistral
const ollamaResponse = $input.first().json;
const rawResponse = ollamaResponse.response || '';
const documentData = $('Extraire Texte OCR').first().json;

let parsed = {};
try {
  let cleaned = rawResponse
    .replace(/```json\n?/g, '')
    .replace(/```\n?/g, '')
    .trim();
  const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('Pas de JSON trouvé dans la réponse');
  }
} catch (e) {
  parsed = {
    emetteur: null,
    type_document: 'courrier_administratif',
    montant_total: null,
    date_document: null,
    date_echeance: null,
    iban: null,
    bic: null,
    communication: null,
    numero_facture: null,
    statut_paiement: 'Non Payé',
    notes: `Erreur parsing IA: ${e.message}`
  };
}

// Normalisation
const normalize = (obj) => {
  if (obj.montant_total !== null && typeof obj.montant_total === 'string') {
    obj.montant_total = parseFloat(obj.montant_total.replace(',', '.').replace(/[^0-9.]/g, '')) || null;
  }
  if (!['facture', 'rappel', 'courrier_administratif', 'attestation'].includes(obj.type_document)) {
    obj.type_document = 'courrier_administratif';
  }
  if (!['Non Payé', 'Payé', 'En Litige', 'Rappel Reçu'].includes(obj.statut_paiement)) {
    obj.statut_paiement = obj.type_document === 'rappel' ? 'Rappel Reçu' : 'Non Payé';
  }
  return obj;
};
parsed = normalize(parsed);

// -------------------------------------------------------------------------
// QR Code EPC — génération 100% locale (bibliothèque `qrcode` npm)
// Aucun appel réseau externe — standard EPC069-12 v002 (12 champs)
//
// Champ 12 (Information au bénéficiaire) : date limite de paiement
// Visible dans l'appli bancaire après scan, rappelle l'échéance à l'utilisateur
// Note : le standard EPC ne supporte pas de date d'exécution forcée —
//        la date ici est informative uniquement.
// -------------------------------------------------------------------------
let qrEpcBase64 = null;
if (parsed.iban && parsed.montant_total && parsed.montant_total > 0) {
  try {
    const qrcode = require('qrcode');
    const ibanClean = parsed.iban.replace(/\s/g, '');
    const beneficiary = (parsed.emetteur || '').substring(0, 70);
    const amount = parsed.montant_total.toFixed(2);
    const communication = (parsed.communication || parsed.numero_facture || '').substring(0, 140);

    // Champ 12 : date limite de paiement (DD/MM/YYYY, lisible dans l'appli bancaire)
    let infoEcheance = '';
    if (parsed.date_echeance) {
      const d = new Date(parsed.date_echeance);
      const day   = String(d.getUTCDate()).padStart(2, '0');
      const month = String(d.getUTCMonth() + 1).padStart(2, '0');
      const year  = d.getUTCFullYear();
      infoEcheance = `À payer avant le ${day}/${month}/${year}`;
    }

    // Standard EPC069-12 v002 — 12 champs séparés par \n
    const epcPayload = [
      'BCD',                                // 1. Service tag
      '002',                               // 2. Version
      '1',                                 // 3. Encodage UTF-8
      'SCT',                               // 4. SEPA Credit Transfer
      parsed.bic || '',                    // 5. BIC (optionnel)
      beneficiary,                         // 6. Nom bénéficiaire (max 70)
      ibanClean,                           // 7. IBAN
      `EUR${amount}`,                      // 8. Montant (ex: EUR125.50)
      '',                                  // 9. Code motif (optionnel, vide)
      '',                                  // 10. Réf structurée (vide)
      communication,                       // 11. Réf non structurée (max 140)
      infoEcheance.substring(0, 70),      // 12. Info bénéf. = date limite paiement
    ].join('\n');

    qrEpcBase64 = await qrcode.toDataURL(epcPayload, {
      errorCorrectionLevel: 'M',
      width: 300,
      margin: 2,
      color: { dark: '#000000', light: '#ffffff' }
    });
  } catch (e) {
    console.error('[easy-GED] Erreur génération QR EPC:', e.message);
  }
}

return [{
  json: {
    document_id: documentData.document_id,
    file_name: documentData.file_name,
    ...parsed,
    qr_epc_base64: qrEpcBase64,
    processed_at: new Date().toISOString()
  }
}];

