// Calculer les jours restants avant échéance + préparer notification
const data = $('Parser Réponse IA').first().json;
const today = new Date();
let joursRestants = null;
let urgence = false;

if (data.date_echeance) {
  const echeance = new Date(data.date_echeance);
  joursRestants = Math.ceil((echeance - today) / (1000 * 60 * 60 * 24));
  urgence = joursRestants <= 7;
}

return [{
  json: {
    ...data,
    jours_restants: joursRestants,
    urgence: urgence,
    message_titre: urgence
      ? `🚨 URGENT — Facture à payer dans ${joursRestants} jour(s) !`
      : `📄 Nouvelle facture reçue`,
    message_corps: [
      `📧 Émetteur : ${data.emetteur || 'Inconnu'}`,
      data.numero_facture ? `🔢 Référence : ${data.numero_facture}` : null,
      data.montant_total !== null ? `💶 Montant : ${data.montant_total.toFixed(2)} €` : null,
      data.date_echeance ? `📅 Échéance : ${data.date_echeance}${joursRestants !== null ? ` (${joursRestants}j)` : ''}` : null,
      data.iban ? `🏦 IBAN : ${data.iban}` : null,
      data.communication ? `📝 Réf paiement : ${data.communication}` : null,
      data.qr_epc_base64 ? `\n📱 QR Code EPC joint dans l'email pour paiement mobile` : null
    ].filter(Boolean).join('\n')
  }
}];

// Construire le corps HTML de l'email avec QR Code EPC embarqué
// Le QR code est en base64 — aucun lien externe, 100% auto-hébergé
const data = $input.first().json;

const montantStr = data.montant_total !== null
  ? data.montant_total.toFixed(2) + ' €'
  : 'Non renseigné';

const echeanceStr = data.date_echeance
  ? (() => {
      const d = new Date(data.date_echeance);
      const day   = String(d.getUTCDate()).padStart(2, '0');
      const month = String(d.getUTCMonth() + 1).padStart(2, '0');
      const year  = d.getUTCFullYear();
      return `${day}/${month}/${year}`;
    })()
  : null;

// Section QR Code — uniquement si IBAN + montant disponibles
const qrSection = data.qr_epc_base64 ? `
  <hr style="border: none; border-top: 1px solid #e0e0e0; margin: 20px 0;">
  <h3 style="color: #1a73e8; margin-bottom: 8px;">📱 Paiement mobile — QR Code EPC</h3>
  <p style="color: #555; margin: 0 0 12px;">Scannez ce QR code avec votre application bancaire pour préremplir le virement SEPA.</p>
  <img src="${data.qr_epc_base64}" alt="QR Code EPC SEPA" width="200" height="200"
    style="display: block; border: 1px solid #ddd; border-radius: 8px; padding: 8px; background: #fff;">
  ${echeanceStr ? `<p style="color: #e53935; font-weight: bold; margin: 10px 0 0;">⏰ À payer avant le ${echeanceStr}</p>` : ''}
  <p style="color: #888; font-size: 12px; margin: 6px 0 0;">La date est affichée à titre informatif dans le QR code (champ 12 standard EPC069-12).</p>
` : '';

const html = `
<!DOCTYPE html>
<html lang="fr">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"></head>
<body style="font-family: Arial, sans-serif; color: #333; max-width: 600px; margin: 0 auto; padding: 20px;">

  <div style="background: ${data.urgence ? '#ffebee' : '#e8f5e9'}; border-left: 4px solid ${data.urgence ? '#e53935' : '#43a047'}; padding: 16px 20px; border-radius: 4px; margin-bottom: 20px;">
    <h2 style="margin: 0; color: ${data.urgence ? '#b71c1c' : '#2e7d32'}; font-size: 18px;">${data.message_titre}</h2>
  </div>

  <table style="width: 100%; border-collapse: collapse; margin-bottom: 16px;">
    <tr style="border-bottom: 1px solid #eee;">
      <td style="padding: 10px 8px; color: #666; width: 140px;">📧 Émetteur</td>
      <td style="padding: 10px 8px; font-weight: bold;">${data.emetteur || 'Non renseigné'}</td>
    </tr>
    ${data.numero_facture ? `<tr style="border-bottom: 1px solid #eee;"><td style="padding: 10px 8px; color: #666;">🔢 Référence</td><td style="padding: 10px 8px;">${data.numero_facture}</td></tr>` : ''}
    <tr style="border-bottom: 1px solid #eee;">
      <td style="padding: 10px 8px; color: #666;">💶 Montant</td>
      <td style="padding: 10px 8px; font-weight: bold; font-size: 16px;">${montantStr}</td>
    </tr>
    ${echeanceStr ? `<tr style="border-bottom: 1px solid #eee;"><td style="padding: 10px 8px; color: #666;">📅 Échéance</td><td style="padding: 10px 8px; color: ${data.urgence ? '#e53935' : '#333'}; font-weight: ${data.urgence ? 'bold' : 'normal'};">Le ${echeanceStr}${data.jours_restants !== null ? ` — dans ${data.jours_restants} jour(s)` : ''}</td></tr>` : ''}
    ${data.iban ? `<tr style="border-bottom: 1px solid #eee;"><td style="padding: 10px 8px; color: #666;">🏦 IBAN</td><td style="padding: 10px 8px; font-family: monospace; font-size: 13px;">${data.iban}</td></tr>` : ''}
    ${data.communication ? `<tr style="border-bottom: 1px solid #eee;"><td style="padding: 10px 8px; color: #666;">📝 Communication</td><td style="padding: 10px 8px;">${data.communication}</td></tr>` : ''}
  </table>

  ${qrSection}

  <hr style="border: none; border-top: 1px solid #e0e0e0; margin: 20px 0;">
  <p style="color: #999; font-size: 11px; margin: 0;">
    Document : ${data.file_name} &nbsp;|&nbsp; Traité le : ${data.processed_at}<br>
    <strong>easy-GED</strong> — Votre GED privée auto-hébergée
  </p>

</body>
</html>`;

return [{
  json: {
    ...data,
    email_html: html
  }
}];

// Vérifier si une facture payée du même émetteur correspond au rappel
const rappelData = $('Parser Réponse IA').first().json;
const searchResults = $('Chercher Facture Payée').first().json;

const rappelMontant = rappelData.montant_total;
const documents = searchResults.results || [];

let facturePayeeTrouvee = null;

for (const doc of documents) {
  const fields = doc.custom_fields || [];
  const montantField = fields.find(f => f.field === 'montant_total');
  const statutField = fields.find(f => f.field === 'statut_paiement');

  if (statutField && statutField.value === 'Payé') {
    if (rappelMontant === null) {
      facturePayeeTrouvee = doc;
      break;
    }
    if (montantField && montantField.value !== null) {
      const montantDoc = parseFloat(montantField.value);
      const tolerance = rappelMontant * 0.05;
      if (Math.abs(montantDoc - rappelMontant) <= tolerance) {
        facturePayeeTrouvee = doc;
        break;
      }
    }
  }
}

const litige = facturePayeeTrouvee !== null;

return [{
  json: {
    ...rappelData,
    litige: litige,
    facture_payee: facturePayeeTrouvee ? {
      id: facturePayeeTrouvee.id,
      titre: facturePayeeTrouvee.title,
      url: `${process.env.PAPERLESS_URL || 'http://localhost:8000'}/documents/${facturePayeeTrouvee.id}/`
    } : null,
    message_titre: litige
      ? `⚠️ LITIGE DÉTECTÉ — Rappel abusif de ${rappelData.emetteur || 'Émetteur inconnu'} !`
      : `🔔 Rappel de paiement reçu`,
    message_corps: litige
      ? [
          `🚨 Un rappel a été reçu de ${rappelData.emetteur || 'inconnu'} alors qu'une facture similaire est marquée comme PAYÉE.`,
          rappelData.montant_total !== null ? `💶 Montant du rappel : ${rappelData.montant_total.toFixed(2)} €` : null,
          `📄 Facture payée correspondante : ${facturePayeeTrouvee.title}`,
          `🔗 Voir dans Paperless : ${process.env.PAPERLESS_URL || 'http://localhost:8000'}/documents/${facturePayeeTrouvee.id}/`,
          `\n⚡ ACTION REQUISE : Contester ce rappel avec la preuve de paiement jointe.`
        ].filter(Boolean).join('\n')
      : [
          `📧 Émetteur : ${rappelData.emetteur || 'Inconnu'}`,
          rappelData.montant_total !== null ? `💶 Montant : ${rappelData.montant_total.toFixed(2)} €` : null,
          rappelData.date_echeance ? `📅 Échéance : ${rappelData.date_echeance}` : null,
          `\n⚡ ACTION REQUISE : Vérifier et régler ce rappel.`
        ].filter(Boolean).join('\n')
  }
}];

